contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint a) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (a)); require(a <= 1000000000000000000000000000000);
        require(a > 0);
        require(address(this).balance >= a);

        uint testBalBefore = address(this).balance;

        c.deposit{value: a}(); if (__ESBMC_reverted()) return;
        uint cBalAfterDeposit = address(c).balance;

        c.withdrawAll(); if (__ESBMC_reverted()) return;
        uint cBalAfterWithdraw = address(c).balance;

        assert(
            cBalAfterDeposit >= a &&
            cBalAfterWithdraw == cBalAfterDeposit - a &&
            address(this).balance == testBalBefore
        );
    }

    receive() external payable {}
}

