// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 a) internal {
        a = bound(a, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(a > 0);
        vm.assume(address(this).balance >= a);
        uint testBalBefore = address(this).balance;
        try c.deposit{value: a}() {} catch { return; }
        uint cBalAfterDeposit = address(c).balance;
        try c.withdrawAll() {} catch { return; }
        uint cBalAfterWithdraw = address(c).balance;
        assertTrue(cBalAfterDeposit >= a &&
            cBalAfterWithdraw == cBalAfterDeposit - a &&
            address(this).balance == testBalBefore);
    }

    function testFuzz_run(uint256 a) public {
        _run(a);
    }

    receive() external payable {}
}
